#!/usr/bin/env python3
"""jflat: flatten a JSON document into flat ``key=value`` lines, and back.

Usage:
    cat doc.json | python3 jflat.py [--sep SEP]            > flat.txt
    cat flat.txt | python3 jflat.py --unflatten [--sep SEP] > doc.json

Format
------
Every leaf value becomes one line ``key=value``, where ``key`` is the path of
object keys / array indices joined by SEP (default ``.``):

    {"a": {"b": [10, 20]}}      ->      a.b.0=10
                                        a.b.1=20

Values are rendered as JSON scalars (``json.dumps``).  Consequently:

Empty-container markers
    An empty object is written as the literal value ``{}``.
    An empty array  is written as the literal value ``[]``.

        {"a": {}, "b": []}      ->      a={}
                                        b=[]

A document that *is* an empty object/array flattens to the single bare line
``{}`` or ``[]`` (no ``=``).  On --unflatten, a value of exactly ``{}`` or
``[]`` becomes an empty object/array respectively (values are parsed as JSON,
and these are precisely their JSON spellings).

Escaping
    Separator characters occurring *inside* a key are escaped so that
    unflattening is lossless.  The escape character is backslash (``\\``):

        ``\\``  ->  ``\\\\``   (a literal backslash in a key)
        SEP     ->  ``\\`` + SEP   (a separator inside a key, e.g. ``.`` -> ``\\.``)
        ``=``   ->  ``\\=``    (protects the key=value delimiter)

    Example (SEP = ``.``): the key ``a.b`` flattens as ``a\\.b=1``.

Arrays vs objects on --unflatten
    A path level whose keys are *exactly* the consecutive integers
    ``0 .. n-1`` is reconstructed as an array; anything else (including
    ``{}``/``[]`` markers, which carry no children) becomes an object.  Note
    that a JSON object whose keys happen to be exactly ``"0".."n-1"`` therefore
    canonicalises to an array on a round trip; every other object round-trips
    unchanged.

Restrictions
    SEP must be non-empty and must not contain a newline.  Object keys must
    not contain newlines (the format is one value per line).
"""

import argparse
import json
import sys

DEFAULT_SEP = "."
ESCAPE = "\\"
EMPTY_OBJECT = "{}"
EMPTY_ARRAY = "[]"


# --------------------------------------------------------------------------- #
# key-component encoding / decoding
# --------------------------------------------------------------------------- #

def escape_component(component: str, sep: str) -> str:
    """Escape a single path component so it can safely be joined with *sep*."""
    if "\n" in component or "\r" in component:
        raise ValueError(f"key contains a newline: {component!r}")
    out = component.replace(ESCAPE, ESCAPE + ESCAPE)
    out = out.replace(sep, ESCAPE + sep)
    out = out.replace("=", ESCAPE + "=")
    return out


def _decode_from(encoded: str, sep: str, start: int, stop: int) -> str:
    """Undo escaping on encoded[start:stop]; ``\\X`` yields literal X, and
    ``\\`` + SEP yields SEP (needed when SEP itself contains ``=`` or ``\\``)."""
    out = []
    i = start
    while i < stop:
        ch = encoded[i]
        if ch == ESCAPE:
            if encoded.startswith(sep, i + 1):
                out.append(sep)
                i += 1 + len(sep)
            elif i + 1 < stop:
                out.append(encoded[i + 1])
                i += 2
            else:
                raise ValueError(f"dangling escape in key: {encoded!r}")
        else:
            out.append(ch)
            i += 1
    return "".join(out)


def split_key(encoded: str, sep: str) -> list:
    """Split an encoded key on *unescaped* occurrences of *sep*, then unescape
    each component."""
    parts = []
    start = 0
    i = 0
    while i < len(encoded):
        if encoded[i] == ESCAPE:
            if encoded.startswith(sep, i + 1):
                i += 1 + len(sep)
            elif i + 1 < len(encoded):
                i += 2
            else:
                raise ValueError(f"dangling escape in key: {encoded!r}")
        elif encoded.startswith(sep, i):
            parts.append(_decode_from(encoded, sep, start, i))
            start = i = i + len(sep)
        else:
            i += 1
    return parts + [_decode_from(encoded, sep, start, len(encoded))]


# --------------------------------------------------------------------------- #
# flatten
# --------------------------------------------------------------------------- #

def _render_value(value) -> str:
    # json.dumps already renders {} and [] exactly as our markers.
    return json.dumps(value)


def flatten(doc, sep: str = DEFAULT_SEP) -> str:
    """Flatten a JSON-compatible document into newline-separated key=value lines."""
    if sep == "":
        raise ValueError("separator must be non-empty")
    if "\n" in sep or "\r" in sep:
        raise ValueError("separator must not contain newlines")
    if not isinstance(doc, (dict, list)):
        raise ValueError("top-level JSON document must be an object or array")

    lines = []

    def walk(path: list, value) -> None:
        if isinstance(value, dict):
            if not value:
                lines.append(sep.join(path) + "=" + EMPTY_OBJECT if path else EMPTY_OBJECT)
            else:
                for key, sub in value.items():
                    if not isinstance(key, str):
                        raise ValueError(f"object key is not a string: {key!r}")
                    walk(path + [escape_component(key, sep)], sub)
        elif isinstance(value, list):
            if not value:
                lines.append(sep.join(path) + "=" + EMPTY_ARRAY if path else EMPTY_ARRAY)
            else:
                for index, sub in enumerate(value):
                    walk(path + [str(index)], sub)
        else:
            lines.append(sep.join(path) + "=" + _render_value(value))

    walk([], doc)
    return "\n".join(lines)


# --------------------------------------------------------------------------- #
# unflatten
# --------------------------------------------------------------------------- #

def _is_consecutive_indices(children: dict) -> bool:
    n = len(children)
    return n > 0 and set(children) == {str(i) for i in range(n)}


def _materialise(node):
    """Bottom-up conversion: levels keyed by exactly 0..n-1 become arrays."""
    if not isinstance(node, dict):
        return node
    materialised = {key: _materialise(child) for key, child in node.items()}
    if _is_consecutive_indices(materialised):
        return [materialised[str(i)] for i in range(len(materialised))]
    return materialised


def unflatten(text: str, sep: str = DEFAULT_SEP):
    """Reconstruct a JSON document from flattened key=value lines."""
    if sep == "":
        raise ValueError("separator must be non-empty")
    if "\n" in sep or "\r" in sep:
        raise ValueError("separator must not contain newlines")

    lines = [line for line in text.split("\n") if line.strip()]
    if not lines:
        raise ValueError("no input lines to unflatten")

    if len(lines) == 1 and "=" not in lines[0]:
        if lines[0] in (EMPTY_OBJECT, EMPTY_ARRAY):
            return json.loads(lines[0])
        raise ValueError(f"malformed line (missing '='): {lines[0]!r}")

    root = {}
    for lineno, line in enumerate(lines, 1):
        key_part, eq, value_part = line.partition("=")
        if not eq:
            raise ValueError(f"line {lineno}: malformed (missing '='): {line!r}")
        try:
            value = json.loads(value_part)
        except json.JSONDecodeError as exc:
            raise ValueError(f"line {lineno}: bad JSON value {value_part!r}: {exc}") from None
        components = split_key(key_part, sep)

        node = root
        for depth, component in enumerate(components):
            last = depth == len(components) - 1
            if last:
                if component in node:
                    raise ValueError(f"line {lineno}: duplicate path for key {component!r}")
                node[component] = value
            else:
                child = node.get(component)
                if child is None:
                    child = {}
                    node[component] = child
                elif not isinstance(child, dict):
                    raise ValueError(
                        f"line {lineno}: key {component!r} is both a leaf and a branch"
                    )
                node = child

    return _materialise(root)


# --------------------------------------------------------------------------- #
# CLI
# --------------------------------------------------------------------------- #

def main(argv=None) -> int:
    parser = argparse.ArgumentParser(
        prog="jflat",
        description=(
            "Flatten JSON from stdin into key=value lines (one leaf per line, "
            "path components joined by SEP), or --unflatten such lines back "
            "into JSON."
        ),
        epilog=(
            "format details:\n"
            "  Empty-container markers: an empty OBJECT is written as the\n"
            "  literal value '{}'; an empty ARRAY as '[]'.  A top-level empty\n"
            "  object/array flattens to the single bare line '{}' or '[]'.\n"
            "\n"
            "  Escaping: separator characters inside keys are escaped with a\n"
            "  backslash: '\\' becomes '\\\\', SEP becomes '\\' + SEP (so with\n"
            "  the default SEP '.', a key 'a.b' flattens as 'a\\\\.b'), and '='\n"
            "  becomes '\\=' to protect the key=value delimiter.\n"
            "\n"
            "  On --unflatten, a level whose keys are exactly the consecutive\n"
            "  integers 0..n-1 is reconstructed as an array; anything else\n"
            "  becomes an object."
        ),
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument(
        "--unflatten",
        action="store_true",
        help="reconstruct JSON from flattened lines instead of flattening",
    )
    parser.add_argument(
        "--sep",
        default=DEFAULT_SEP,
        metavar="SEP",
        help=f"path component separator (default: {DEFAULT_SEP!r}); "
             "occurrences of SEP inside keys are escaped",
    )
    args = parser.parse_args(argv)

    data = sys.stdin.read()
    try:
        if args.unflatten:
            doc = unflatten(data, sep=args.sep)
            sys.stdout.write(json.dumps(doc, indent=2) + "\n")
        else:
            doc = json.loads(data)
            sys.stdout.write(flatten(doc, sep=args.sep) + "\n")
    except (ValueError, json.JSONDecodeError) as exc:
        print(f"jflat: error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

