"""Tests for jflat.py: round-trip property over seeded random documents,
plus targeted empty-container and separator-escaping cases."""

import json
import os
import random
import subprocess
import sys

import pytest

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import jflat  # noqa: E402


# --------------------------------------------------------------------------- #
# helpers
# --------------------------------------------------------------------------- #

TRICKY_KEYS = [
    "a.b",          # contains the default separator
    "x=y",          # key/value delimiter inside a key
    "back\\slash",  # literal backslash
    "-",            # dash (first char of the '->' separator)
    "->",           # whole '->' separator as a key
    "::",           # whole '::' separator as a key
    "|",            # another tested separator
    "",             # empty key
    "{}",           # looks like the empty-object marker
    "[]",           # looks like the empty-array marker
    "0",            # single numeric-ish key (not a full 0..n-1 set by itself)
    "ünïcode",      # non-ascii
]

SEPS = [".", "->", "::", "|"]


def make_key(rng):
    """Random key; never all-digits, so object levels never accidentally look
    like arrays (that canonicalisation is covered by targeted tests)."""
    if rng.random() < 0.25:
        return rng.choice(TRICKY_KEYS)
    alphabet = "abcdefghijklmnopqrstuvwxyz"
    return "".join(rng.choice(alphabet) for _ in range(rng.randint(1, 8)))


def rand_scalar(rng):
    return rng.choice([
        None, True, False, 0, 1, -42, 3.14, -0.5, 1e300, "",
        "plain string", 'quote"inside', "with=equals", "with.dot",
        "line\\break", "{}", "[]",
    ])


def rand_doc(rng, depth=4):
    """Random nested document. Dict keys are never all-digit strings."""
    roll = rng.random()
    if depth <= 0 or roll < 0.35:
        return rand_scalar(rng)
    if roll < 0.72:
        return {make_key(rng): rand_doc(rng, depth - 1)
                for _ in range(rng.randint(0, 5))}
    return [rand_doc(rng, depth - 1) for _ in range(rng.randint(0, 5))]


# --------------------------------------------------------------------------- #
# round-trip property: 100 seeded random nested documents x several separators
# --------------------------------------------------------------------------- #

def test_round_trip_property_100_seeded_documents():
    for seed in range(100):
        rng = random.Random(seed)
        doc = rand_doc(rng)
        for sep in SEPS:
            flat = jflat.flatten(doc, sep=sep)
            restored = jflat.unflatten(flat, sep=sep)
            assert restored == doc, (
                f"round-trip failed for seed={seed}, sep={sep!r}\n"
                f"flat:\n{flat}"
            )


def test_round_trip_preserves_json_dumps():
    """Round trip must also preserve the exact JSON serialisation."""
    rng = random.Random(999)
    for seed in range(20):
        doc = rand_doc(random.Random(seed))
        for sep in SEPS:
            assert json.dumps(jflat.unflatten(jflat.flatten(doc, sep), sep),
                              sort_keys=True) == json.dumps(doc, sort_keys=True)


# --------------------------------------------------------------------------- #
# targeted: basic flattening shape
# --------------------------------------------------------------------------- #

def test_flatten_basic_shape():
    doc = {"a": {"b": [10, 20]}}
    assert jflat.flatten(doc) == "a.b.0=10\na.b.1=20"


def test_flatten_scalar_types():
    doc = {"n": None, "t": True, "f": False, "i": 7, "fl": 1.5, "s": "hi"}
    lines = jflat.flatten(doc).splitlines()
    assert lines == [
        "n=null", "t=true", "f=false", "i=7", "fl=1.5", 's="hi"',
    ]


def test_unflatten_reconstructs_arrays_from_consecutive_indices():
    assert jflat.unflatten("a.0=x\na.1=y\na.2=z") == {"a": ["x", "y", "z"]}


def test_unflatten_non_consecutive_indices_stay_object():
    assert jflat.unflatten("a.0=x\na.2=y") == {"a": {"0": "x", "2": "y"}}


def test_unflatten_object_with_digit_keys_canonicalises_to_array():
    # documented behaviour: exactly 0..n-1 keys at a level become an array
    assert jflat.unflatten('a.0="0"\na.1=1') == {"a": ["0", 1]}


# --------------------------------------------------------------------------- #
# targeted: empty containers
# --------------------------------------------------------------------------- #

def test_empty_container_markers_in_values():
    doc = {"a": {}, "b": []}
    assert jflat.flatten(doc) == "a={}\nb=[]"
    assert jflat.unflatten("a={}\nb=[]") == doc


def test_nested_empty_containers():
    doc = {"outer": {"mid": {"deep": {}}, "lst": [[], [[]]]}}
    flat = jflat.flatten(doc)
    assert flat.splitlines() == [
        "outer.mid.deep={}",
        "outer.lst.0=[]",
        "outer.lst.1.0=[]",
    ]
    assert jflat.unflatten(flat) == doc


def test_top_level_empty_containers_are_bare_marker_lines():
    assert jflat.flatten({}) == "{}"
    assert jflat.flatten([]) == "[]"
    assert jflat.unflatten("{}") == {}
    assert jflat.unflatten("[]") == []
    # with a custom separator too
    assert jflat.flatten({}, sep="->") == "{}"
