def split_key_value(line: str, sep: str = DEFAULT_SEP):
    """Split ``key=value`` at the first UNESCAPED '='; returns (key, value)
    or None if the line has no unescaped '='.

    Escape-aware: after ESCAPE the scanner consumes ESCAPE+SEP or two chars,
    mirroring how escape_component emits sequences."""
    i = 0
    n = len(line)
    while i < n:
        if line[i] == ESCAPE:
            if line.startswith(sep, i + 1):
                i += 1 + len(sep)
            elif i + 1 < n:
                i += 2
            else:
                return None  # dangling escape -> malformed
        elif line[i] == "=":
            return line[:i], line[i + 1:]
        else:
            i += 1
    return None

